// Monta a mensagem por kind (voz da Mi). Telefone E.164 -> só dígitos.
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const number = String(d.telefone || '').replace(/\D/g, '');
  if (!number) continue;
  const nome = d.nome || '';
  let text;
  switch (d.kind) {
    case 'aniversario': // <!-- APROVAR COM A MI -->
      text = `Feliz aniversário, ${nome}! 💛\n\nQue seu dia seja tão lindo quanto você. Passa aqui pra gente comemorar com um cuidado especial. 💛`;
      break;
    case 'aniversario_cliente': // <!-- APROVAR COM A MI -->
      text = `Oi, ${nome}! 💛\n\nFaz 1 ano que a gente se conheceu — obrigada pela confiança desde então. Bora marcar um próximo encontro?`;
      break;
    case 'pos_atendimento': { // <!-- APROVAR COM A MI -->
      const svc = d.servico ? ` de ${d.servico}` : '';
      text = `Oi, ${nome}! 💛\n\nFoi um prazer te atender${svc} ontem. Como você se sentiu? Se puder, me conta — e se topar, adoraria registrar o resultado (só com a sua autorização). 💛`;
      break;
    }
    case 'reconexao': // <!-- APROVAR COM A MI -->
      text = `Oi, ${nome}! 💛\n\nFaz um tempinho que a gente não se vê — saudades! Que tal remarcar um cuidado pra você? É só me chamar por aqui.`;
      break;
    default:
      continue;
  }
  out.push({ json: { number, text, kind: d.kind, dedup_key: d.dedup_key } });
}
return out;
